DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT120-S1-Q26$batch13$ AND q.stimulus=$batch13$Researchers gave 100 first-graders after-school lessons in handwriting. They found that those whose composition skills had improved the most had learned to write letters the most automatically. This suggests that producing characters more automatically frees up mental resources for other activities.$batch13$ AND q.prompt=$batch13$Which one of the following, if true, most strengthens the argument?$batch13$ AND q.correct_choice=$batch13$C$batch13$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q26'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch13$6a6a5f87-7508-4b44-b9d4-9cf861b94c26$batch13$) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch13$6a6a5f87-7508-4b44-b9d4-9cf861b94c26$batch13$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT120-S1-Q26'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$This links practice to automatic handwriting. Composition never comes into it, so it says nothing about freeing up mental resources.$batch13$), ($batch13$B$batch13$, $batch13$This is about kids who were already automatic before the lessons. The argument is about becoming more automatic during them. Those kids might also just be stronger students overall, so this doesn't show automaticity freed anything up.$batch13$), ($batch13$C$batch13$, $batch13$Across the group, bigger gains in automatic handwriting came with bigger gains in composition. That's the pattern you'd expect if automatic writing frees attention for composing.$batch13$), ($batch13$D$batch13$, $batch13$A representative sample lets the result generalize. It doesn't support the causal claim about why automatic handwriting helps.$batch13$), ($batch13$E$batch13$, $batch13$This suggests strong composition skills led to more automatic handwriting. That reverses the argument's direction of cause.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT120-S1-Q26$batch13$ AND e.id=$batch13$6a6a5f87-7508-4b44-b9d4-9cf861b94c26$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
